// Checkout conversion module - ensures paid events are tracked
const axios = require('axios');

module.exports = {
  async processCheckout(session) {
    // Simulate checkout processing
    if (!session || !session.id) {
      console.error('Invalid session');
      return { success: false, error: 'Invalid session' };
    }
    // Record paid event
    try {
      await axios.post('http://localhost:4000/api/revenue/event', {
        type: 'paid',
        sessionId: session.id,
        amount: session.amount || 0,
        timestamp: new Date().toISOString()
      });
      console.log('Paid event recorded for session', session.id);
      return { success: true };
    } catch (err) {
      console.error('Failed to record paid event:', err.message);
      return { success: false, error: err.message };
    }
  },

  async validateConversion(sessionId) {
    // Check if session has a paid event
    try {
      const res = await axios.get(`http://localhost:4000/api/revenue/event/${sessionId}`);
      return res.data && res.data.paid;
    } catch {
      return false;
    }
  }
};
